def get_large_corpus(min_tokens: int = 4096, tokenizer=None) -> str:
    """
    Returns non-repeating natural text with up to 30,000 tokens.
    """
    # Join all distinct paragraphs
    text = "\n\n".join(CORPUS_PARAGRAPHS)
    if tokenizer is not None:
        tokens = tokenizer(text, return_tensors="pt").input_ids
        cur_len = tokens.shape[1]
        if cur_len < min_tokens:
            # If even more tokens are needed, synthesize distinct domain-prefixed paragraphs
            extra_needed = min_tokens - cur_len
            extra_paras = []
            for i in range(max(1, extra_needed // 25)):
                extra_paras.append(
                    f"Domain study chapter {i+1} section {i*7%13}: "
                    f"Systematic empirical investigation into structural parameter {i*17%101} demonstrates "
                    f"invariant scaling behavior under controlled laboratory conditions with confidence interval {0.95 + (i%5)*0.01:.3f}."
                )
            text = text + "\n\n" + "\n\n".join(extra_paras)
    return text
